import java.util.Scanner;
class ShoppingCart{
    void calculateTotal(double a){
        System.out.println(a);
    }
    void calculateTotal(double a, double b){
        System.out.println(a+b);
    }
    void calculateTotal(double a,double b, double c){
        System.out.println((a-(a*(c/100)))+(b-(b*(c/100))));
    }
}
public class Main{
    public static void main(String arg[]){
        Scanner sc = new Scanner(System.in);
        ShoppingCart s = new ShoppingCart();
        String inp = sc.nextLine();
        String[] parts= inp.split(" ");
        double[] p = new double[3];
        p[0]=0;
        p[1]=0;
        p[2]=0;
        for(int i=0;i<parts.length();i++){
            p[i] = Double.parseDouble(parts[i]);
        }
        if (p[0]>0 && (p[1]<=0 && p[2]<=0)){
            s.calculateTotal(p[0]);
        }
        else if ((p[0]>0 && p[1]>0) && p[2]<=0){
            s.calculateTotal(p[0],p[1]);
        }
        else if (p[0]>0 && p[1]>0 && p[2]>0){
            s.calculateTotal(p[0],p[1],p[2]);
        }
        else{
            System.out.println("Invalid Input");
        }


    }
}


whats wroong

